                put( "fetchTickers", new ArrayList<Object>(Arrays.asList(primarySymbol)) );
                put( "fetchLastPrices", new ArrayList<Object>(Arrays.asList(primarySymbol)) );
                put( "fetchOHLCV", new ArrayList<Object>(Arrays.asList(primarySymbol)) );
                put( "fetchTrades", new ArrayList<Object>(Arrays.asList(primarySymbol)) );
                put( "fetchOrderBook", new ArrayList<Object>(Arrays.asList(primarySymbol)) );
                put( "fetchOrderBooks", new ArrayList<Object>(Arrays.asList()) );
