                    put( "watchMyTrades", new ArrayList<Object>(Arrays.asList(symbol)) );
                    put( "watchOrders", new ArrayList<Object>(Arrays.asList(symbol)) );
                    put( "watchPosition", new ArrayList<Object>(Arrays.asList(symbol)) );
