    public CompletableFuture<Object> testReturnResponseHeaders(Exchange exchange)
    {

        return BaseExchange.supplyAsync(() -> {

            if (!java.util.Objects.equals(exchange.id, "binance"))
            {
                return false;  // this test is only for binance exchange for now
            }
            exchange.returnResponseHeaders = true;
            Object ticker = ((CompletableFuture<Object>)Helpers.callDynamically(exchange, "fetchTicker", new Object[]{"BTC/USDT", new HashMap<String, Object>() {{}}})).join();
            Object info = ((Map<String, Object>)ticker).get("info");
            Object headers = Helpers.GetValue(info, "responseHeaders");
            List<Object> headersKeys = Helpers.objectKeys(headers);
            Assert(((List<?>)headersKeys).size() > 0, "Response headers should not be empty");
            Object headerValues = Helpers.objectValues(headers);
            Assert(((List<?>)headerValues).size() > 0, "Response headers values should not be empty");
            exchange.returnResponseHeaders = false;
            return true;
        });

    }

    public CompletableFuture<Object> startTest(BaseExchange exchange, Object symbolArgv)
    {

        return BaseExchange.supplyAsync(() -> {

            // we do not need to test aliases
            if (java.util.Objects.equals(exchange.alias, true))
            {
                return true;
            }
            this.checkConstructor(exchange);
            // await this.testReturnResponseHeaders (exchange);
            if (Helpers.isTrue(this.sandbox) || (java.util.Objects.equals(getExchangeProp(exchange, "sandbox"), true)))
            {
                exchange.setSandboxMode(true);
            }
            this.testHasProps(exchange);
            try
            {
                Object result = (this.loadExchange(exchange)).join();
                if (!Helpers.isTrue(result))
                {
                    if (!Helpers.isTrue(isSync()))
                    {
                        (close(exchange)).join();
                    }
                    return true;
                }
                // if (exchange.id === 'binance') {
                //     // we test proxies functionality just for one random exchange on each build, because proxy functionality is not exchange-specific, instead it's all done from base methods, so just one working sample would mean it works for all ccxt exchanges
                //     // await this.testProxies (exchange);
                // }
                (this.testExchange(exchange, symbolArgv)).join();
                if (!Helpers.isTrue(isSync()))
                {
                    (close(exchange)).join();
                }
            } catch(Exception e)
            {
                if (!Helpers.isTrue(isSync()))
                {
                    (close(exchange)).join();
                }
                throw (e instanceof RuntimeException ? (RuntimeException)e : new RuntimeException(e));
            }
            return true;  // required in c#
        });

    }

